function UIBattlingBubbleDialog:OnUnitEnter(data)
    -- printInfo("OnUnitEnter " .. table.dump(data))

    if next(data) ~= nil then
        for i = 1, #data do
            local t = {}
            t.target = UIBattlingBubbleDialog.GetRoleIdFromBattle(data[i].id)
            t.param = BubbleCondition.UnitEnter
            self:TriggerBubble(BubbleCondition.UnitEnter, t)
        end
        
    end
end

