function UIBattlingBubbleDialog:GetWaveData()
    --BattleViewMgr.levelData
    for i, v in pairs(BattleViewMgr.levelData) do
        -- printInfo("wave %d, data %s", i, table.dump(v))
        if v.bubble ~= 0 then
            for j = 1, #v.bubble do
                local vo = UIBattlingBubbleDialog.GetBubbleVo(v.bubble[j])
                if vo ~= nil then
                    self:AnalyzeBubble(i, vo)
                end
            end
        end
    end

    if self.BubbleData ~= nil then
        for i, v in pairs(self.BubbleData) do
            -- printInfo("%d %s", i, table.dump(v))
        end
        self.initialized = true
    else
        self.initialized = false
    end
    
    if not isSet(self.BubbleData, BubbleCondition.UnitHp) then
        return
    end
    
    local tmp = {}
    local arr = self.BubbleData[BubbleCondition.UnitHp]
    for i = 1, #arr do
        if not isSet(tmp, arr[i].wave) then
            tmp[arr[i].wave] = {}
        end
        if not isSet(tmp[arr[i].wave], arr[i].target) then
            tmp[arr[i].wave][arr[i].target] = {}
        end
        local t = {}
        t.hp = arr[i].param
        t.index = i
        table.insert(tmp[arr[i].wave][arr[i].target], t)
    end
    for i, v in pairs(tmp) do
        -- printInfo("wave %d, result %s",i,table.dump(v))
        for key, value in pairs(v) do
            table.sort(value, function(a, b)
                return a.hp > b.hp
            end)
            -- printInfo(table.dump(value))
            for index = 1, #value - 1 do
                local up = value[index]
                local down = value[index + 1]
                arr[up.index].param2 = down.hp
            end
        end
    end
    
    -- printInfo("after %s", table.dump(arr))
end

---@param vo BattleBubbleVo
function UIBattlingBubbleDialog:AnalyzeBubble(wave, vo)
    if self.BubbleData == nil then
        self.BubbleData = {}
    end

    if not isSet(self.BubbleData, vo.condition) then
        self.BubbleData[vo.condition] = {}
    end
    
    local t = {}
    t.wave = wave
    t.condition = vo.condition
    t.target = checkNumber(vo.param[1])
    t.param = checkNumber(vo.param[2])
    t.cacheVo = vo
    t.triggerTimes = vo.triggerTimes
    t.enable = true
    if vo.condition == BubbleCondition.UnitHp then
        t.param2 = 0
    elseif vo.condition == BubbleCondition.Round or vo.condition == BubbleCondition.Wave then
        t.param = t.target
        t.target = vo.condition
    elseif vo.condition == BubbleCondition.UnitEnter then
        t.param = vo.condition
    end
    
    table.insert(self.BubbleData[vo.condition], t)
end

function UIBattlingBubbleDialog:DisableBubble(wave)
    if self.BubbleData == nil then
        return
    end
    -- printInfo("DisableBubble %d", wave)
    for i, v in pairs(self.BubbleData) do
        for j = 1, #v do
            if wave == v[j].wave then
                v[j].enable = false
            end
        end
    end
end

---@param param table @{target,param}
function UIBattlingBubbleDialog:TriggerBubble(condition, param)
    if self.blockLogic then
       return 
    end
    
    if param == nil or param.target == nil  then
        return
    end
    
    if self.BubbleData == nil then
        return
    end

    if not isSet(self.BubbleData, condition) then
        return
    end
    -- printInfo("param %d, %s",condition, table.dump(param))

    local arr = self.BubbleData[condition]
    local trigger = nil
    for i = 1, #arr do
        --printInfo(table.dump(arr[i]))
        if arr[i].enable and arr[i].target == param.target and (arr[i].triggerTimes == -1 or arr[i].triggerTimes > 0) then
            if condition == BubbleCondition.UnitHp then
                if arr[i].param >= param.param and arr[i].param2 < param.param then
                    trigger = arr[i]
                    if arr[i].triggerTimes ~= -1 then
                        arr[i].triggerTimes = arr[i].triggerTimes - 1
                    end
                    
                    break
                end
            else
                if arr[i].param == param.param then
                    trigger = arr[i]
                    if arr[i].triggerTimes ~= -1 then
                        arr[i].triggerTimes = arr[i].triggerTimes - 1
                    end
                    break
                end

            end
        end
    end
    
    
    if trigger == nil then
        return
    end

    -- printInfo("trigger %s", table.dump(trigger))
    --if self.CachedCo == nil then
    --    self.CachedCo = {}
    --end

    --if isSet(self.CachedCo, trigger.cacheVo.pos) then
    --    cs_coroutine.stop(self.CachedCo[trigger.cacheVo.pos])
    --end

    if self.CachedCo ~= nil then
        cs_coroutine.stop(self.CachedCo)
        self.CachedCo = nil
    end

    KTool.SetActive(self.BubbleUp.gameObject, false)
    KTool.SetActive(self.BubbleDown.gameObject, false)
    
    self.CachedCo = cs_coroutine.start(self.StartBubble, self, trigger.cacheVo)
    
end

---@param trigger BattleBubbleVo
function UIBattlingBubbleDialog:StartBubble(trigger)
    
    :: start ::
    ---@type UIBattlingBubbleNode
    local env = trigger.pos == BubblePos.Down and self.bubbleDownEnv or self.bubbleUpEnv
    local anim = trigger.pos == BubblePos.Down and self.BubbleDown or self.BubbleUp
    local playName = trigger.pos == BubblePos.Down and "down" or "up"
    anim = anim.gameObject:GetComponent(typeof(Animator))
    if not KTool.IsActiveInHierarchy(anim.gameObject) then
        KTool.SetActive(anim.gameObject, true)
        anim:Play(playName)
    end
    
    -- printInfo("start bubble %s", table.dump(trigger))
    coroutine.yield(env:StartBubble(trigger))
    
    coroutine.yield(Yielders.GetWaitForSeconds(AnimTime))

    if trigger.next ~= 0 then
        trigger = UIBattlingBubbleDialog.GetBubbleVo(trigger.next)
        goto start
    end
    
    coroutine.yield(Yielders.GetWaitForSeconds(BubbleDisappearTime))

    KTool.SetActive(self.BubbleUp.gameObject, false)
    KTool.SetActive(self.BubbleDown.gameObject, false)
    
end

function UIBattlingBubbleDialog:InitBubbleEnv()
    self.bubbleUpEnv = GetLuaBehaviour(self.BubbleUp.gameObject, BubbleNodePath)
    if isNull(self.bubbleUpEnv.Env) then
        self.bubbleUpEnv:Init()
    end
    self.bubbleUpEnv = self.bubbleUpEnv.Env
    self.bubbleDownEnv = GetLuaBehaviour(self.BubbleDown.gameObject, BubbleNodePath)
    if isNull(self.bubbleDownEnv.Env) then
        self.bubbleDownEnv:Init()
    end
    self.bubbleDownEnv = self.bubbleDownEnv.Env
end


