function UIBattlingBubbleDialog.GetRoleIdFromBattle(roleId)
    local roleData = UIBattlingDataMgr:GetRoleDataByRoleId(roleId)
    if isNull(roleData) then
        return nil
    end
    local camp = UIBattlingDataMgr:GetRoleCampByRoleId(roleId)
    if camp == nil then
        return nil
    end
    -- printInfo("GetRoleIdFromBattle %s", table.dump(roleData))
    local id = not BattleInfo:IsUserCamp(camp) and roleData.enemyId or roleData.cardId
    return id
end

function UIBattlingBubbleDialog.GetBubbleVo(bubbleId)
    local Setting = SettingMgr:GetSetting(AutoIds.IdSetting378, "BattleBubbleVo")
    local vo = Setting:Get(bubbleId)
    return vo
end

